#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <sys/prctl.h>
#include <unistd.h>
int main(void) {
 const char *comm=getenv("FIXTURE_COMM"), *ready=getenv("FIXTURE_READY");
 if (!comm || !ready || prctl(PR_SET_NAME,comm,0,0,0)) return 90;
 FILE *out=fopen(ready,"w"); if (!out) return 91;
 fputs("ready\n",out); if (fclose(out)) return 92;
 alarm(20); for (;;) pause();
}

